import React, { useEffect, useState } from "react";
import { createRoot } from "react-dom/client";
import { ArrowLeft, ArrowRight, Check, ChevronDown, CircleHelp, CirclePlay, Clapperboard, CloudUpload, Download, FileAudio, Film, FolderOpen, Gauge, History, ImagePlus, Languages, LayoutDashboard, Library, LogOut, Menu, Mic2, Moon, MoreHorizontal, Pause, Play, Plus, RefreshCw, RotateCcw, Settings, ShieldCheck, Sparkles, Sun, Trash2, Upload, Volume2, WandSparkles, X } from "lucide-react";
import "./styles.css";

const api = async (path, options = {}, token) => {
  const headers = new Headers(options.headers || {});
  if (token) headers.set("Authorization", `Bearer ${token}`);
  if (options.body && !(options.body instanceof FormData)) headers.set("Content-Type", "application/json");
  const response = await fetch(path, { ...options, headers });
  const raw = await response.text();
  let data = {};
  try { data = raw ? JSON.parse(raw) : {}; } catch { data = { error: raw || "The server returned an invalid response." }; }
  if (!response.ok) throw new Error(data.error || `Request failed (${response.status}).`);
  return data;
};

const initialDraft = { title: "", topic: "", language: "km", durationMinutes: 1, script: "", aspectRatio: "16:9", resolution: "1280x720" };

function App() {
  const [session, setSession] = useState(null);
  const [booting, setBooting] = useState(true);
  const [theme, setTheme] = useState(() => localStorage.getItem("toolaime-theme") || "dark");
  useEffect(() => { document.documentElement.dataset.theme = theme; localStorage.setItem("toolaime-theme", theme); }, [theme]);
  useEffect(() => {
    const token = localStorage.getItem("toolaime-token");
    if (!token) { setBooting(false); return; }
    api("/api/v1/auth/me", {}, token).then(({ user }) => setSession({ token, user })).catch(() => localStorage.removeItem("toolaime-token")).finally(() => setBooting(false));
  }, []);
  function signOut() { localStorage.removeItem("toolaime-token"); setSession(null); }
  if (booting) return <div className="app-loading"><div className="loading-mark"><img src="/toolaime-logo.jpg" alt="ToolAiMe" /></div><span>Loading ToolAiMe…</span></div>;
  if (!session) return <AuthScreen onAuthenticated={setSession} />;
  return <Workspace session={session} onSignOut={signOut} theme={theme} onTheme={() => setTheme(theme === "dark" ? "light" : "dark")} />;
}

function AuthScreen({ onAuthenticated }) {
  const [mode, setMode] = useState("login");
  const [form, setForm] = useState({ name: "", email: "", password: "" });
  const [busy, setBusy] = useState(false); const [error, setError] = useState("");
  async function submit(event) {
    event.preventDefault(); setError("");
    if (form.password.length < 8) { setError("Use a password with at least 8 characters."); return; }
    setBusy(true);
    try { const data = await api(`/api/v1/auth/${mode === "login" ? "login" : "register"}`, { method: "POST", body: JSON.stringify(form) }); localStorage.setItem("toolaime-token", data.accessToken); onAuthenticated({ token: data.accessToken, user: data.user }); }
    catch (submitError) { setError(submitError.message); } finally { setBusy(false); }
  }
  return <div className="auth-shell"><div className="auth-visual"><div className="auth-brand"><div className="brand-icon"><img src="/toolaime-logo.jpg" alt="ToolAiMe" /></div><span>ToolAiMe</span></div><div className="auth-visual-copy"><span className="kicker">AI VIDEO AUTOMATION STUDIO</span><h1>From a Khmer idea to a finished video.</h1><p>Create, shape, and render original stories in one focused workspace.</p></div><div className="visual-orbit orbit-a" /><div className="visual-orbit orbit-b" /><div className="auth-mini-preview"><div className="mini-preview-art"><Film size={28} /></div><div><strong>Phase 1 workspace</strong><span>Script → media → MP4</span></div><Check size={17} /></div></div><div className="auth-panel"><div className="auth-panel-inner"><span className="mobile-kicker">TOOLAIME</span><h2>{mode === "login" ? "Welcome back" : "Create your workspace"}</h2><p className="muted">{mode === "login" ? "Sign in to continue creating." : "Start your first Khmer video project."}</p>{error && <div className="alert error"><X size={16} />{error}</div>}<form className="stack-form" onSubmit={submit}>{mode === "register" && <Field label="Name" value={form.name} placeholder="Your name" onChange={(value) => setForm({ ...form, name: value })} autoComplete="name" />}<Field label="Email" type="email" value={form.email} placeholder="you@example.com" onChange={(value) => setForm({ ...form, email: value })} autoComplete="email" /><Field label="Password" type="password" value={form.password} placeholder="At least 8 characters" onChange={(value) => setForm({ ...form, password: value })} autoComplete={mode === "login" ? "current-password" : "new-password"} /><button className="button primary full" disabled={busy}>{busy ? <Spinner /> : mode === "login" ? "Sign in" : "Create account"}</button></form><div className="auth-switch"><span>{mode === "login" ? "New to ToolAiMe?" : "Already have an account?"}</span><button onClick={() => { setMode(mode === "login" ? "register" : "login"); setError(""); }}>{mode === "login" ? "Create account" : "Sign in"}</button></div><p className="auth-note"><ShieldCheck size={14} /> Your projects and files stay scoped to your account.</p></div></div></div>;
}

function Field({ label, value, onChange, type = "text", placeholder, autoComplete }) { return <label className="field"><span>{label}</span><input type={type} value={value} placeholder={placeholder} autoComplete={autoComplete} onChange={(event) => onChange(event.target.value)} required /></label>; }

function Workspace({ session, onSignOut, theme, onTheme }) {
  const [view, setView] = useState("overview"); const [mobileNav, setMobileNav] = useState(false); const [projects, setProjects] = useState([]); const [notice, setNotice] = useState(null); const [activeProject, setActiveProject] = useState(null);
  async function loadProjects() { try { const data = await api("/api/v1/projects", {}, session.token); setProjects(data.projects || []); } catch (error) { setNotice({ type: "error", text: error.message }); } }
  useEffect(() => { loadProjects(); }, []);
  function navigate(nextView) { setView(nextView); setMobileNav(false); setNotice(null); }
  function openProject(project) { setActiveProject(project); setView("generator"); setMobileNav(false); }
  return <div className="studio-shell"><aside className={`sidebar ${mobileNav ? "open" : ""}`}><div className="sidebar-top"><div className="brand-lockup"><div className="brand-icon"><img src="/toolaime-logo.jpg" alt="ToolAiMe" /></div><div><strong>ToolAiMe</strong><small>AI VIDEO STUDIO</small></div></div><button className="icon-button mobile-close" onClick={() => setMobileNav(false)}><X size={18} /></button></div><div className="workspace-user"><div className="avatar">{session.user.name.slice(0, 1).toUpperCase()}</div><div><strong>{session.user.name}</strong><span>Personal workspace</span></div><ChevronDown size={15} /></div><nav className="nav-groups"><NavGroup label="Workspace"><NavItem icon={LayoutDashboard} label="Overview" active={view === "overview"} onClick={() => navigate("overview")} /><NavItem icon={Clapperboard} label="AI Video Generator" active={view === "generator"} onClick={() => navigate("generator")} badge="PHASE 1" /><NavItem icon={Library} label="Media Library" active={view === "library"} onClick={() => navigate("library")} /></NavGroup><NavGroup label="AI tools"><NavItem icon={Mic2} label="Khmer AI Voice" active={view === "voice"} onClick={() => navigate("voice")} soon /><NavItem icon={Languages} label="Chinese Story Recap" active={view === "recap"} onClick={() => navigate("recap")} soon /></NavGroup><NavGroup label="Publishing"><NavItem icon={CirclePlay} label="Auto Publisher" active={view === "publisher"} onClick={() => navigate("publisher")} soon /><NavItem icon={Gauge} label="Analytics" active={view === "analytics"} onClick={() => navigate("analytics")} soon /></NavGroup></nav><div className="sidebar-footer"><NavItem icon={Settings} label="Settings" active={view === "settings"} onClick={() => navigate("settings")} /><button className="nav-item" onClick={onSignOut}><LogOut size={17} /> Sign out</button><div className="sidebar-footnote"><CircleHelp size={14} /> Phase 1 · Local storage</div></div></aside><main className="main-area"><header className="topbar"><button className="icon-button menu-trigger" onClick={() => setMobileNav(true)}><Menu size={20} /></button><div className="breadcrumbs"><span>ToolAiMe</span><span>/</span><strong>{view === "overview" ? "Overview" : view === "generator" ? "AI Video Generator" : titleForView(view)}</strong></div><div className="topbar-actions"><button className="icon-button" onClick={onTheme} aria-label="Toggle color theme">{theme === "dark" ? <Sun size={18} /> : <Moon size={18} />}</button><div className="top-avatar">{session.user.name.slice(0, 1).toUpperCase()}</div></div></header><div className="page-content">{notice && <div className={`alert ${notice.type}`}><span>{notice.type === "success" ? <Check size={16} /> : <X size={16} />}</span>{notice.text}<button onClick={() => setNotice(null)}><X size={15} /></button></div>}{view === "overview" && <Overview projects={projects} onOpenProject={openProject} onCreate={() => { setActiveProject(null); navigate("generator"); }} />}{view === "generator" && <Generator token={session.token} project={activeProject} onProjectChange={setActiveProject} onProjectsChange={loadProjects} onNotice={setNotice} onBack={() => navigate("overview")} />}{view === "library" && <ProjectLibrary projects={projects} onOpen={openProject} onCreate={() => { setActiveProject(null); navigate("generator"); }} />}{view !== "overview" && view !== "generator" && view !== "library" && <ComingSoon view={view} onBack={() => navigate("overview")} />}</div></main></div>;
}

function titleForView(view) { return { voice: "Khmer AI Voice", recap: "Chinese Story Recap", publisher: "Auto Publisher", analytics: "Analytics", settings: "Settings" }[view] || "Overview"; }
function NavGroup({ label, children }) { return <div className="nav-group"><span className="nav-label">{label}</span>{children}</div>; }
function NavItem({ icon: Icon, label, active, onClick, badge, soon }) { return <button className={`nav-item ${active ? "active" : ""}`} onClick={onClick}><Icon size={17} /><span>{label}</span>{badge && <em>{badge}</em>}{soon && !["Khmer AI Voice", "Chinese Story Recap"].includes(label) && <small>SOON</small>}</button>; }

function Overview({ projects, onOpenProject, onCreate }) {
  const completed = projects.filter((project) => project.status === "COMPLETED").length;
  return <><section className="page-intro"><div><span className="eyebrow">CREATOR WORKSPACE</span><h1>Make something <span>worth watching.</span></h1><p>Build original videos in Khmer with a simple, review-first workflow.</p></div><button className="button primary" onClick={onCreate}><Plus size={17} /> New video project</button></section><div className="stats-row"><Stat label="Total projects" value={projects.length} icon={FolderOpen} /><Stat label="Completed videos" value={completed} icon={Film} /><Stat label="AI script status" value="Ready" icon={Sparkles} /><Stat label="Publishing" value="Later" icon={CirclePlay} muted /></div><section className="section-heading"><div><span className="eyebrow">TOOLBOX</span><h2>Choose your next move</h2></div><span className="section-meta">Phase 1 of 8</span></section><div className="tool-grid"><ToolCard icon={Clapperboard} tone="violet" title="AI Video Generator" description="Generate a Khmer script, add your own media, and render a real MP4." action="Start a project" onClick={onCreate} live /><ToolCard icon={Mic2} tone="amber" title="Khmer AI Voice" description="Turn a script into polished Khmer narration with provider-backed voices." action="Coming soon" /><ToolCard icon={Languages} tone="blue" title="Chinese Story Recap" description="Analyze Chinese stories and craft natural Khmer recaps." action="Coming soon" /><ToolCard icon={CirclePlay} tone="green" title="Auto Publisher" description="Approve finished videos before publishing to YouTube and Facebook Pages." action="Not configured" /></div><section className="section-heading recent-heading"><div><span className="eyebrow">RECENT WORK</span><h2>Your projects</h2></div><span className="section-meta">{projects.length} total</span></section><ProjectRows projects={projects} onOpen={onOpenProject} emptyAction={onCreate} /></>;
}
function Stat({ label, value, icon: Icon, muted }) { return <div className="stat-card"><div className="stat-icon"><Icon size={17} /></div><div><span>{label}</span><strong className={muted ? "muted-value" : ""}>{value}</strong></div></div>; }
function ToolCard({ icon: Icon, tone, title, description, action, onClick, live }) { return <article className={`tool-card ${tone} ${live ? "clickable" : ""}`} onClick={live ? onClick : undefined} tabIndex={live ? 0 : undefined}><div className="tool-card-art"><div className="art-grid" /><div className="art-orb" /><div className="art-icon"><Icon size={27} /></div><span className="art-label">{live ? "READY TO BUILD" : "COMING SOON"}</span></div><div className="tool-card-copy"><div><h3>{title}</h3><p>{description}</p></div><button className={live ? "card-action" : "card-action disabled"} onClick={live ? onClick : undefined} disabled={!live}>{live ? <>{action}<ArrowRight size={16} /></> : action}</button></div></article>; }
function ProjectRows({ projects, onOpen, emptyAction }) { return <div className="project-list">{projects.length === 0 ? <div className="empty-state"><div className="empty-icon"><FolderOpen size={22} /></div><h3>No projects yet</h3><p>Start with a topic and build your first Khmer video.</p><button className="button secondary" onClick={emptyAction}><Plus size={16} /> Create a project</button></div> : projects.slice(0, 5).map((project) => <button className="project-row" key={project.id} onClick={() => onOpen(project)}><div className="project-thumb"><Film size={18} /></div><div className="project-row-name"><strong>{project.title}</strong><span>{project.topic}</span></div><StatusBadge status={project.status} /><span className="project-date">{formatDate(project.updatedAt)}</span><MoreHorizontal size={17} /></button>)}</div>; }
function StatusBadge({ status }) { const label = String(status || "DRAFT").replaceAll("_", " "); return <span className={`status-badge ${status === "COMPLETED" ? "success" : status === "RENDERING" ? "working" : ""}`}><i />{label}</span>; }
function ProjectLibrary({ projects, onOpen, onCreate }) { return <><section className="page-intro compact"><div><span className="eyebrow">MEDIA LIBRARY</span><h1>Your video projects</h1><p>Open a project to continue editing or render the final MP4.</p></div><button className="button primary" onClick={onCreate}><Plus size={17} /> New project</button></section><ProjectRows projects={projects} onOpen={onOpen} emptyAction={onCreate} /></>; }

function Generator({ token, project, onProjectChange, onProjectsChange, onNotice, onBack }) {
  const [step, setStep] = useState(project ? 2 : 1); const [draft, setDraft] = useState(project ? { ...initialDraft, ...project } : initialDraft); const [media, setMedia] = useState(project?.mediaAssets || []); const [renderJob, setRenderJob] = useState(project?.renderJobs?.[0] || null); const [busy, setBusy] = useState(false); const [voiceBusy, setVoiceBusy] = useState(false); const [voiceSample, setVoiceSample] = useState(null); const [consentAudio, setConsentAudio] = useState(null); const [voiceConsent, setVoiceConsent] = useState(false); const [error, setError] = useState("");
  useEffect(() => { if (!project) { setStep(1); setDraft(initialDraft); setMedia([]); setRenderJob(null); setVoiceSample(null); setConsentAudio(null); setVoiceConsent(false); return; } setDraft({ ...initialDraft, ...project }); setMedia(project.mediaAssets || []); setRenderJob(project.renderJobs?.[0] || null); setVoiceSample(null); setConsentAudio(null); setVoiceConsent(false); setStep(project.script ? 2 : 1); }, [project?.id]);
  function update(field, value) { setDraft((current) => ({ ...current, [field]: value })); }
  async function save(patch = draft) { if (!project) return; const data = await api(`/api/v1/projects/${project.id}`, { method: "PATCH", body: JSON.stringify(patch) }, token); onProjectChange(data.project); setDraft({ ...initialDraft, ...data.project }); await onProjectsChange(); return data.project; }
  async function createProject(event) { event.preventDefault(); setError(""); if (!draft.title.trim() || !draft.topic.trim()) { setError("Add a title and topic to continue."); return; } setBusy(true); try { const data = await api("/api/v1/projects", { method: "POST", body: JSON.stringify(draft) }, token); onProjectChange(data.project); setDraft({ ...initialDraft, ...data.project }); await onProjectsChange(); setStep(2); } catch (createError) { setError(createError.message); } finally { setBusy(false); } }
  async function generateScript() { if (!project) return; setBusy(true); setError(""); try { const data = await api("/api/v1/gemini/generate-script", { method: "POST", body: JSON.stringify({ projectId: project.id, topic: draft.topic, language: draft.language, durationMinutes: draft.durationMinutes }) }, token); update("script", data.script); onProjectChange(data.project); await onProjectsChange(); onNotice({ type: "success", text: `Script generated with ${data.provider}.` }); } catch (generateError) { setError(generateError.message); } finally { setBusy(false); } }
  async function saveScript() { setBusy(true); setError(""); try { await save({ script: draft.script, topic: draft.topic, language: draft.language, durationMinutes: draft.durationMinutes, title: draft.title }); onNotice({ type: "success", text: "Script saved." }); setStep(3); } catch (saveError) { setError(saveError.message); } finally { setBusy(false); } }
  async function generateSimilarVoice() { if (!project || !voiceSample || !consentAudio || !voiceConsent || !draft.script.trim()) return; setVoiceBusy(true); setError(""); try { await save({ script: draft.script, topic: draft.topic, language: draft.language, durationMinutes: draft.durationMinutes, title: draft.title }); const form = new FormData(); form.append("script", draft.script); form.append("consent", "true"); form.append("sourceAudio", voiceSample); form.append("consentAudio", consentAudio); const data = await api(`/api/v1/projects/${project.id}/voice/generate`, { method: "POST", body: form }, token); setMedia((current) => [data.asset, ...current]); await onProjectsChange(); onNotice({ type: "success", text: "Similar voice narration generated. Review it before rendering." }); setStep(3); } catch (voiceError) { setError(voiceError.message); } finally { setVoiceBusy(false); } }
  async function uploadFiles(files) { if (!project || !files.length) return; setBusy(true); setError(""); try { for (const file of files) { const form = new FormData(); form.append("file", file); const data = await api(`/api/v1/projects/${project.id}/media`, { method: "POST", body: form }, token); setMedia((current) => [...current, data.asset]); } await onProjectsChange(); onNotice({ type: "success", text: "Media uploaded to the project." }); } catch (uploadError) { setError(uploadError.message); } finally { setBusy(false); } }
  async function deleteAsset(asset) { try { await api(`/api/v1/media/${asset.id}`, { method: "DELETE" }, token); setMedia((current) => current.filter((item) => item.id !== asset.id)); } catch (deleteError) { setError(deleteError.message); } }
  async function moveImage(index, direction) { const images = media.filter((item) => item.type === "IMAGE"); const next = index + direction; if (next < 0 || next >= images.length) return; [images[index], images[next]] = [images[next], images[index]]; try { await Promise.all(images.map((item, order) => api(`/api/v1/media/${item.id}`, { method: "PATCH", body: JSON.stringify({ displayOrder: order }) }, token))); setMedia((current) => [...images, ...current.filter((item) => item.type !== "IMAGE")]); } catch (moveError) { setError(moveError.message); } }
  async function startRender() { if (!project) return; setBusy(true); setError(""); try { await save({ aspectRatio: draft.aspectRatio, resolution: draft.resolution }); const data = await api(`/api/v1/projects/${project.id}/render`, { method: "POST", body: JSON.stringify({ aspectRatio: draft.aspectRatio, resolution: draft.resolution }) }, token); setRenderJob(data.job); setStep(5); pollJob(data.job.id); } catch (renderError) { setError(renderError.message); } finally { setBusy(false); } }
  async function pollJob(jobId) { for (let attempt = 0; attempt < 180; attempt += 1) { await new Promise((resolve) => setTimeout(resolve, 1000)); try { const data = await api(`/api/v1/render-jobs/${jobId}`, {}, token); setRenderJob(data.job); if (data.job.status === "COMPLETED") { setStep(6); await onProjectsChange(); onNotice({ type: "success", text: "Your MP4 is ready to preview and download." }); return; } if (data.job.status === "FAILED") { setError(data.job.errorMessage || "FFmpeg render failed."); return; } } catch (pollError) { setError(pollError.message); return; } } setError("Rendering is taking longer than expected. Reopen the project to check its status."); }
  const images = media.filter((item) => item.type === "IMAGE").sort((a, b) => a.displayOrder - b.displayOrder); const audio = media.find((item) => item.type === "AUDIO"); const videos = media.filter((item) => item.type === "VIDEO"); const previewUrl = renderJob?.downloadUrl ? `${renderJob.downloadUrl}?token=${encodeURIComponent(token)}&inline=1` : "";
  return <section className="generator-shell"><div className="wizard-top"><button className="text-button" onClick={onBack}><ArrowLeft size={15} /> Back to overview</button><span className="wizard-project-label">{project?.title || "New video project"}</span></div><div className="wizard-heading"><div><span className="eyebrow">AI VIDEO GENERATOR</span><h1>{project?.title || "Create a new project"}</h1><p>{project ? "Move through the workflow one step at a time. Nothing publishes automatically." : "Start with the story you want to tell."}</p></div><span className="phase-pill"><Sparkles size={14} /> Phase 1</span></div><WizardSteps step={step} onStep={(value) => value <= (project ? 6 : 1) && setStep(value)} />{error && <div className="alert error"><X size={16} />{error}<button onClick={() => setError("")}><X size={15} /></button></div>}<div className="wizard-card card">{step === 1 && <ProjectDetails draft={draft} update={update} busy={busy} onSubmit={createProject} />}{step === 2 && <ScriptStep draft={draft} update={update} busy={busy || voiceBusy} voiceBusy={voiceBusy} voiceSample={voiceSample} consentAudio={consentAudio} voiceConsent={voiceConsent} onVoiceSample={setVoiceSample} onConsentAudio={setConsentAudio} onVoiceConsent={setVoiceConsent} onGenerate={generateScript} onGenerateVoice={generateSimilarVoice} onSave={saveScript} onBack={() => setStep(1)} />}{step === 3 && <MediaStep token={token} images={images} audio={audio} videos={videos} busy={busy} onUpload={uploadFiles} onDelete={deleteAsset} onMove={moveImage} onNext={() => setStep(4)} onBack={() => setStep(2)} />}{step === 4 && <SettingsStep draft={draft} update={update} onBack={() => setStep(3)} onNext={startRender} busy={busy} />}{step === 5 && <RenderStep job={renderJob} onCancel={() => setStep(4)} />}{step === 6 && <FinalStep previewUrl={previewUrl} job={renderJob} onBack={() => setStep(4)} onNew={() => { onProjectChange(null); setStep(1); setDraft(initialDraft); setMedia([]); setRenderJob(null); }} />}</div></section>;
}

function WizardSteps({ step, onStep }) { const steps = ["Project", "Script", "Media", "Settings", "Rendering", "Final video"]; return <div className="wizard-steps">{steps.map((label, index) => <button key={label} className={`${index + 1 === step ? "active" : ""} ${index + 1 < step ? "done" : ""}`} onClick={() => onStep(index + 1)}><span>{index + 1 < step ? <Check size={13} /> : index + 1}</span><strong>{label}</strong></button>)}</div>; }
function StepHeading({ number, title, description }) { return <div className="step-heading"><span className="step-number">{number}</span><div><h2>{title}</h2><p>{description}</p></div></div>; }
function ProjectDetails({ draft, update, onSubmit, busy }) { return <form className="step-content" onSubmit={onSubmit}><StepHeading number="01" title="Project details" description="Give your video a clear working title and topic." /><div className="form-grid"><Field label="Project title" value={draft.title} placeholder="e.g. The kindness of a village" onChange={(value) => update("title", value)} /><Field label="Topic or story idea" value={draft.topic} placeholder="What should the story be about?" onChange={(value) => update("topic", value)} /></div><div className="form-grid three"><label className="field"><span>Language</span><select value={draft.language} onChange={(event) => update("language", event.target.value)}><option value="km">Khmer · ខ្មែរ</option><option value="en">English</option></select></label><label className="field"><span>Target duration</span><select value={draft.durationMinutes} onChange={(event) => update("durationMinutes", Number(event.target.value))}><option value="1">1 minute</option><option value="3">3 minutes</option><option value="5">5 minutes</option><option value="10">10 minutes</option><option value="15">15 minutes</option></select></label></div><div className="step-actions end"><button className="button primary" disabled={busy}>{busy ? <Spinner /> : <>Continue to script <ArrowRight size={16} /></>}</button></div></form>; }
function ScriptStep({ draft, update, busy, voiceBusy, voiceSample, consentAudio, voiceConsent, onVoiceSample, onConsentAudio, onVoiceConsent, onGenerate, onGenerateVoice, onSave, onBack }) { return <div className="step-content"><StepHeading number="02" title="Write the narration" description="Generate an original Khmer script with Gemini, write your own, or create a similar voice reading it." /><div className="script-toolbar"><div className="provider-status"><span className="status-dot" /> Gemini provider <small>Configured on the server</small></div><button className="button secondary" onClick={onGenerate} disabled={busy || !draft.topic}>{busy ? <Spinner /> : <><WandSparkles size={16} /> Generate with Gemini</>}</button></div><label className="field"><span>Script <em>{draft.script.length.toLocaleString()} / 50,000</em></span><textarea className="script-editor" value={draft.script} onChange={(event) => update("script", event.target.value)} placeholder="Write or generate the Khmer narration here…" maxLength={50000} /></label><div className="script-note"><ShieldCheck size={16} /><span>Review AI output before using it. ToolAiMe does not publish or claim rights to source footage automatically.</span></div><div className="voice-generation-panel"><div><span className="eyebrow">SIMILAR VOICE</span><h3>Have your script read in a similar version of your voice</h3><p>Upload a clean 10–30 second sample and a consent recording from the same adult speaker. The one-off voice profile is not stored by ToolAiMe.</p></div><div className="voice-upload-grid"><label className="field"><span>Voice sample · MP3/WAV</span><input type="file" accept="audio/mpeg,audio/wav,.mp3,.wav" onChange={(event) => onVoiceSample(event.target.files?.[0] || null)} /></label><label className="field"><span>Consent recording · MP3/WAV</span><input type="file" accept="audio/mpeg,audio/wav,.mp3,.wav" onChange={(event) => onConsentAudio(event.target.files?.[0] || null)} /></label></div><label className="checkbox-field"><input type="checkbox" checked={voiceConsent} onChange={(event) => onVoiceConsent(event.target.checked)} /><span>I own or control this voice and authorize ToolAiMe to create this similar synthetic voice for my project.</span></label><button className="button secondary" onClick={onGenerateVoice} disabled={busy || voiceBusy || !draft.script.trim() || !voiceSample || !consentAudio || !voiceConsent}>{voiceBusy ? <Spinner /> : <><Mic2 size={16} /> Generate similar voice</>}</button></div><div className="step-actions"><button className="button ghost" onClick={onBack}><ArrowLeft size={16} /> Back</button><button className="button primary" onClick={onSave} disabled={busy || voiceBusy || !draft.script.trim()}>{busy || voiceBusy ? <Spinner /> : <>Save and add media <ArrowRight size={16} /></>}</button></div></div>; }
function UploadZone({ icon: Icon, title, hint, accept, multiple, onFiles }) { return <label className="upload-zone"><input type="file" accept={accept} multiple={multiple} onChange={(event) => { onFiles(Array.from(event.target.files || [])); event.target.value = ""; }} /><div className="upload-icon"><Icon size={20} /></div><strong>{title}</strong><span>{hint}</span><button type="button" className="small-button"><Upload size={14} /> Choose files</button></label>; }
function MediaStep({ token, images, audio, videos, busy, onUpload, onDelete, onMove, onNext, onBack }) { return <div className="step-content"><StepHeading number="03" title="Add your media" description="Upload story images, an optional MP4 source video, and one MP3 or WAV narration." /><div className="media-format-note"><Film size={15} /><span><strong>MP4 source video is supported.</strong> Use the Source video card for MP4 files; narration must still be MP3 or WAV for rendering.</span></div><div className="upload-zones"><UploadZone icon={ImagePlus} title="Story images" hint="JPG, PNG, or WebP · up to 80 MB each" accept="image/jpeg,image/png,image/webp" multiple onFiles={onUpload} /><UploadZone icon={Film} title="Source video (MP4)" hint="MP4 · up to 80 MB" accept="video/mp4,.mp4" onFiles={onUpload} /><UploadZone icon={Mic2} title="Narration audio" hint="MP3 or WAV · one file per project" accept="audio/mpeg,audio/wav,.mp3,.wav" onFiles={onUpload} /></div><div className="media-list">{images.map((asset, index) => <MediaRow key={asset.id} asset={asset} token={token} index={index} count={images.length} onDelete={onDelete} onMove={onMove} />)}{videos.map((asset) => <MediaRow key={asset.id} asset={asset} token={token} video onDelete={onDelete} />)}{audio && <MediaRow asset={audio} token={token} audio onDelete={onDelete} />}{!images.length && !audio && !videos.length && <div className="inline-empty"><CloudUpload size={18} /><span>Your uploaded assets will appear here.</span></div>}</div><div className="step-actions"><button className="button ghost" onClick={onBack}><ArrowLeft size={16} /> Back</button><button className="button primary" onClick={onNext} disabled={busy || !images.length || !audio}>{busy ? <Spinner /> : <>Continue to settings <ArrowRight size={16} /></>}</button></div></div>; }
function MediaRow({ asset, token, audio, video, index, count, onDelete, onMove }) { const src = `${asset.previewUrl}?token=${encodeURIComponent(token)}`; return <div className="media-row">{audio ? <div className="media-preview audio"><FileAudio size={19} /></div> : video ? <video className="media-preview" src={src} controls preload="metadata" /> : <img className="media-preview" src={src} alt={asset.filename} />}<div className="media-name"><strong>{asset.filename}</strong><span>{audio ? "Narration audio" : video ? "MP4 source video" : `Image ${String(index + 1).padStart(2, "0")}`} · {(asset.size / 1024 / 1024).toFixed(1)} MB</span></div>{!audio && !video && <div className="reorder"><button onClick={() => onMove(index, -1)} disabled={index === 0}><ArrowLeft size={14} /></button><button onClick={() => onMove(index, 1)} disabled={index === count - 1}><ArrowRight size={14} /></button></div>}<button className="icon-button danger" onClick={() => onDelete(asset)} aria-label={`Delete ${asset.filename}`}><Trash2 size={16} /></button></div>; }
function SettingsStep({ draft, update, onBack, onNext, busy }) { return <div className="step-content"><StepHeading number="04" title="Video settings" description="Choose the canvas for your finished MP4." /><div className="settings-options"><label className={`choice-card ${draft.aspectRatio === "16:9" ? "selected" : ""}`}><input type="radio" checked={draft.aspectRatio === "16:9"} onChange={() => { update("aspectRatio", "16:9"); update("resolution", "1280x720"); }} /><div className="ratio ratio-landscape" /><div><strong>Landscape</strong><span>16:9 · 1280 × 720</span></div><Check size={17} /></label><label className={`choice-card ${draft.aspectRatio === "9:16" ? "selected" : ""}`}><input type="radio" checked={draft.aspectRatio === "9:16"} onChange={() => { update("aspectRatio", "9:16"); update("resolution", "720x1280"); }} /><div className="ratio ratio-portrait" /><div><strong>Portrait</strong><span>9:16 · 720 × 1280</span></div><Check size={17} /></label></div><div className="settings-note"><ShieldCheck size={17} /><div><strong>Safe local rendering</strong><p>Images are distributed across the narration duration. FFmpeg produces H.264 video with AAC audio and keeps the original aspect ratio inside the chosen canvas.</p></div></div><div className="step-actions"><button className="button ghost" onClick={onBack}><ArrowLeft size={16} /> Back</button><button className="button primary" onClick={onNext} disabled={busy}>{busy ? <Spinner /> : <>Start render <Film size={16} /></>}</button></div></div>; }
function RenderStep({ job, onCancel }) { const progress = Math.max(0, Math.min(100, Number(job?.progress || 0))); return <div className="step-content render-state"><div className="render-icon"><Film size={28} /></div><span className="eyebrow">05 · RENDERING</span><h2>{job?.status === "FAILED" ? "Render needs attention" : "Rendering your video"}</h2><p>{job?.status === "FAILED" ? job.errorMessage : "FFmpeg is combining the images and narration into a playable MP4."}</p><div className="progress-track"><span style={{ width: `${progress}%` }} /></div><div className="render-progress"><strong>{progress}%</strong><span>{job?.status || "QUEUED"}</span></div><button className="button ghost" onClick={onCancel}><ArrowLeft size={16} /> Back to settings</button></div>; }
function FinalStep({ previewUrl, job, onBack, onNew }) { const token = localStorage.getItem("toolaime-token") || ""; return <div className="step-content final-state"><div className="final-heading"><div><span className="eyebrow">06 · FINAL VIDEO</span><h2>Your MP4 is ready</h2><p>Preview the render, then download it for your next workflow.</p></div><span className="complete-badge"><Check size={15} /> Completed</span></div><video className="final-video" src={previewUrl} controls preload="metadata" /><div className="step-actions"><button className="button ghost" onClick={onBack}><ArrowLeft size={16} /> Back to settings</button><a className="button primary" href={job?.downloadUrl ? `${job.downloadUrl}?token=${encodeURIComponent(token)}` : "#"} download><Upload size={16} /> Download MP4</a><button className="button secondary" onClick={onNew}><Plus size={16} /> New project</button></div></div>; }

function VoiceStudio({ onBack }) {
  const token = localStorage.getItem("toolaime-token") || "";
  const [catalog, setCatalog] = useState(null); const [narrations, setNarrations] = useState([]); const [projects, setProjects] = useState([]);
  const [form, setForm] = useState({ title: "Khmer narration", script: "", voice: "Kore", speed: 1, projectId: "" });
  const [selectedId, setSelectedId] = useState(null); const [paragraphIndex, setParagraphIndex] = useState(0); const [recordedFile, setRecordedFile] = useState(null);
  const [busy, setBusy] = useState(false); const [uploadBusy, setUploadBusy] = useState(false); const [paragraphBusy, setParagraphBusy] = useState(false); const [error, setError] = useState(""); const [notice, setNotice] = useState("");
  const selectedNarration = narrations.find((item) => item.id === selectedId) || narrations[0] || null;
  const paragraphs = form.script.split(/\n\s*\n/).map((item) => item.trim()).filter(Boolean);
  const selectedParagraphs = selectedNarration?.script?.split(/\n\s*\n/).map((item) => item.trim()).filter(Boolean) || [];
  function setField(field, value) { setForm((current) => ({ ...current, [field]: value })); }
  async function load() {
    const results = await Promise.allSettled([api("/api/v1/voice/catalog", {}, token), api("/api/v1/voice/narrations", {}, token), api("/api/v1/projects", {}, token)]);
    const [voiceResult, historyResult, projectResult] = results;
    if (voiceResult.status === "fulfilled") setCatalog(voiceResult.value);
    if (historyResult.status === "fulfilled") setNarrations(historyResult.value.narrations || []);
    if (projectResult.status === "fulfilled") setProjects(projectResult.value.projects || []);
    const criticalFailure = voiceResult.status === "rejected" && projectResult.status === "rejected";
    if (criticalFailure) setError(voiceResult.reason?.message || "Voice studio could not load. Try again.");
  }
  useEffect(() => { load(); }, []);
  async function generate() {
    setError(""); setNotice(""); if (!form.script.trim()) { setError("Write a Khmer script before generating narration."); return; }
    setBusy(true); try { const data = await api("/api/v1/voice/narrations", { method: "POST", body: JSON.stringify({ ...form, projectId: form.projectId || null }) }, token); setNarrations((current) => [data.narration, ...current]); setSelectedId(data.narration.id); setNotice("Khmer narration generated. Preview it below before using it in a video."); } catch (generateError) { setError(generateError.message); } finally { setBusy(false); }
  }
  async function uploadRecorded() {
    if (!recordedFile) { setError("Choose an MP3 or WAV recording first."); return; }
    setError(""); setNotice(""); setUploadBusy(true); try { const data = new FormData(); data.append("file", recordedFile); data.append("title", form.title || recordedFile.name); data.append("script", form.script || "Recorded narration"); if (form.projectId) data.append("projectId", form.projectId); const result = await api("/api/v1/voice/upload", { method: "POST", body: data }, token); setNarrations((current) => [result.narration, ...current]); setSelectedId(result.narration.id); setRecordedFile(null); setNotice("Recorded narration uploaded and saved."); } catch (uploadError) { setError(uploadError.message); } finally { setUploadBusy(false); }
  }
  async function regenerateParagraph() {
    if (!selectedNarration) return; setError(""); setNotice(""); setParagraphBusy(true); try { const result = await api(`/api/v1/voice/narrations/${selectedNarration.id}/regenerate-paragraph`, { method: "POST", body: JSON.stringify({ paragraphIndex, voice: selectedNarration.voice === "uploaded" ? "Kore" : selectedNarration.voice, speed: selectedNarration.speed }) }, token); setNarrations((current) => [result.narration, ...current]); setSelectedId(result.narration.id); setNotice(`Paragraph ${paragraphIndex + 1} regenerated.`); } catch (regenerateError) { setError(regenerateError.message); } finally { setParagraphBusy(false); }
  }
  function previewUrl(item) { return `${item.previewUrl}?token=${encodeURIComponent(token)}`; }
  return <section className="voice-studio"><div className="voice-studio-top"><button className="text-button" onClick={onBack}><ArrowLeft size={15} /> Back to overview</button><span className="phase-pill"><Mic2 size={14} /> Phase 2 · Live</span></div><div className="page-intro compact voice-intro"><div><span className="eyebrow">KHMER AI VOICE STUDIO</span><h1>Give your script a voice.</h1><p>Generate natural Khmer narration, adjust the pace, preview the result, and keep every version in your history.</p></div><div className={`voice-provider-badge ${catalog?.configured ? "ready" : "fallback"}`}><span className="status-dot" />{catalog?.configured ? "Gemini TTS ready" : "Recorded upload available"}</div></div>{error && <div className="alert error"><X size={16} />{error}<button onClick={() => setError("")}><X size={15} /></button></div>}{notice && <div className="alert success"><Check size={16} />{notice}<button onClick={() => setNotice("")}><X size={15} /></button></div>}<div className="voice-studio-grid"><section className="card voice-compose"><div className="voice-section-heading"><div><span className="eyebrow">1 · WRITE</span><h2>Khmer narration script</h2></div><span className="char-count">{form.script.length.toLocaleString()} / 30,000</span></div><label className="field"><span>Title</span><input value={form.title} maxLength={120} onChange={(event) => setField("title", event.target.value)} placeholder="e.g. រឿងក្មេងប្រុសអ្នកជួយ" /></label><label className="field"><span>Script</span><textarea className="voice-script-editor" value={form.script} maxLength={30000} onChange={(event) => setField("script", event.target.value)} placeholder="បញ្ចូលអត្ថបទខ្មែរដែលអ្នកចង់ឲ្យសម្លេងអាន…" /></label><div className="voice-form-grid"><label className="field"><span>Voice</span><select value={form.voice} onChange={(event) => setField("voice", event.target.value)}>{(catalog?.voices || [{ id: "Kore", label: "Kore", description: "Clear and balanced" }]).map((voice) => <option key={voice.id} value={voice.id}>{voice.label} · {voice.description}</option>)}</select></label><label className="field"><span>Project (optional)</span><select value={form.projectId} onChange={(event) => setField("projectId", event.target.value)}><option value="">Save to voice history only</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.title}</option>)}</select></label></div><label className="field speed-field"><span>Speaking speed <strong>{Number(form.speed).toFixed(2)}×</strong></span><input type="range" min="0.75" max="1.5" step="0.05" value={form.speed} onChange={(event) => setField("speed", Number(event.target.value))} /></label><div className="speed-labels"><span>Slower</span><span>Natural</span><span>Faster</span></div><div className="voice-actions"><button className="button primary" onClick={generate} disabled={busy || !form.script.trim() || !catalog?.configured}>{busy ? <Spinner /> : <><Volume2 size={16} /> Generate narration</>}</button><span className="voice-action-note">{catalog?.configured ? "Gemini TTS · Khmer script" : "Configure Gemini TTS to generate"}</span></div><div className="voice-upload-card"><div><span className="eyebrow">RECORDED FALLBACK</span><h3>Already have your narration?</h3><p>Upload MP3 or WAV when no TTS provider is available. It can also be attached to a project.</p></div><label className="file-picker"><FileAudio size={16} /><span>{recordedFile?.name || "Choose MP3 or WAV"}</span><input type="file" accept="audio/mpeg,audio/wav,.mp3,.wav" onChange={(event) => setRecordedFile(event.target.files?.[0] || null)} /></label><button className="button secondary" onClick={uploadRecorded} disabled={uploadBusy || !recordedFile}>{uploadBusy ? <Spinner /> : <><Upload size={16} /> Save recording</>}</button></div></section><section className="card voice-history-panel"><div className="voice-section-heading"><div><span className="eyebrow"><History size={13} /> 2 · HISTORY</span><h2>Your narrations</h2></div><span className="section-meta">{narrations.length} saved</span></div>{!selectedNarration && <div className="inline-empty voice-empty"><Mic2 size={20} /><span>Generate or upload a narration to see it here.</span></div>}{selectedNarration && <div className="voice-current"><div className="voice-current-title"><div><strong>{selectedNarration.title}</strong><span>{selectedNarration.provider === "manual-upload" ? "Recorded upload" : `${selectedNarration.voice} · ${Number(selectedNarration.speed).toFixed(2)}×`}</span></div><span className="status-badge success"><i />Ready</span></div><audio controls preload="metadata" src={previewUrl(selectedNarration)} /><div className="voice-current-actions"><a className="button secondary" href={`${selectedNarration.downloadUrl}?token=${encodeURIComponent(token)}`}><Download size={15} /> Download WAV</a>{selectedNarration.projectId && <span className="attached-label"><Check size={14} /> Attached to project</span>}</div>{selectedParagraphs.length > 1 && <div className="paragraph-tools"><label className="field"><span>Regenerate one paragraph</span><select value={paragraphIndex} onChange={(event) => setParagraphIndex(Number(event.target.value))}>{selectedParagraphs.map((paragraph, index) => <option key={index} value={index}>Paragraph {index + 1} · {paragraph.slice(0, 42)}{paragraph.length > 42 ? "…" : ""}</option>)}</select></label><button className="button ghost" onClick={regenerateParagraph} disabled={paragraphBusy}>{paragraphBusy ? <Spinner /> : <><RotateCcw size={15} /> Regenerate paragraph</>}</button></div>}</div>}<div className="voice-history-list">{narrations.map((item) => <button key={item.id} className={`voice-history-row ${item.id === selectedNarration?.id ? "selected" : ""}`} onClick={() => { setSelectedId(item.id); setParagraphIndex(0); }}><div className="history-icon"><FileAudio size={16} /></div><div><strong>{item.title}</strong><span>{item.mode === "PARAGRAPH" ? "Paragraph regeneration" : item.provider === "manual-upload" ? "Recorded upload" : "Gemini TTS"} · {new Date(item.createdAt).toLocaleString()}</span></div><Play size={15} /></button>)}</div></section></div></section>;
}

function ComingSoon({ view, onBack }) { const data = { publisher: { icon: CirclePlay, title: "Auto Publisher", text: "YouTube and Facebook Page publishing will be added after the local render workflow is verified." }, analytics: { icon: Gauge, title: "Analytics", text: "Genuine platform analytics will appear here once publishing integrations are connected." }, settings: { icon: Settings, title: "Settings", text: "Provider, storage, and workspace settings are coming in a later phase." } }[view] || {}; if (view === "voice") return <VoiceStudio onBack={onBack} />; if (view === "recap") return <TimelineVoice onBack={onBack} />; const Icon = data.icon || Sparkles; return <section className="coming-soon"><div className="coming-icon"><Icon size={30} /></div><span className="eyebrow">PLANNED FEATURE</span><h1>{data.title}</h1><p>{data.text}</p><button className="button secondary" onClick={onBack}><ArrowLeft size={16} /> Back to overview</button></section>; }
function Spinner() { return <span className="spinner" aria-label="Loading" />; }
function formatDate(value) { if (!value) return "—"; return new Intl.DateTimeFormat("en", { month: "short", day: "numeric" }).format(new Date(value)); }
createRoot(document.getElementById("root")).render(<App />);

function TimelineVoice({ onBack }) {
  const token = localStorage.getItem("toolaime-token") || "";
  const [catalog, setCatalog] = useState(null); const [projects, setProjects] = useState([]); const [timelines, setTimelines] = useState([]);
  const [title, setTitle] = useState("Khmer story recap timeline"); const [voice, setVoice] = useState("Kore"); const [projectId, setProjectId] = useState(""); const [videoFile, setVideoFile] = useState(null); const [audioFile, setAudioFile] = useState(null); const [srt, setSrt] = useState(""); const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const [timeline, setTimeline] = useState(null);
  async function loadTimelineData() {
    const results = await Promise.allSettled([api("/api/v1/voice/catalog", {}, token), api("/api/v1/projects", {}, token), api("/api/v1/voice/timelines", {}, token)]);
    const [voiceResult, projectResult, timelineResult] = results;
    if (voiceResult.status === "fulfilled") setCatalog(voiceResult.value);
    if (projectResult.status === "fulfilled") setProjects(projectResult.value.projects || []);
    if (timelineResult.status === "fulfilled") setTimelines(timelineResult.value.timelines || []);
    if (voiceResult.status === "rejected" && projectResult.status === "rejected") setError(voiceResult.reason?.message || "Timeline studio could not load. Try again.");
  }
  useEffect(() => { loadTimelineData(); }, []);
  async function exportTimeline() {
    setError(""); if (!videoFile) { setError("Choose an MP4 video first."); return; } if (!srt.trim() && !audioFile) { setError("Paste an SRT subtitle or upload an MP3/WAV narration."); return; }
    setBusy(true); try { const form = new FormData(); form.append("video", videoFile); form.append("title", title); form.append("voice", voice); form.append("srt", srt); if (audioFile) form.append("audio", audioFile); if (projectId) form.append("projectId", projectId); const data = await api("/api/v1/voice/timelines", { method: "POST", body: form }, token); setTimeline(data.timeline); setTimelines((current) => [data.timeline, ...current]); } catch (timelineError) { setError(timelineError.message); } finally { setBusy(false); }
  }
  function src(url) { return url ? `${url}?token=${encodeURIComponent(token)}` : ""; }
  const segmentCount = srt.split(/\n\s*\n/).map((item) => item.trim()).filter(Boolean).length;
  return <section className="timeline-studio"><div className="voice-studio-top"><button className="text-button" onClick={onBack}><ArrowLeft size={15} /> Back to overview</button><span className="phase-pill"><Film size={14} /> Story recap timeline</span></div><div className="page-intro compact"><div><span className="eyebrow">សម្រាយរឿង · TIMELINE VOICE</span><h1>Sync Khmer narration to your story.</h1><p>Upload an authorized MP4, paste its SRT, choose a voice, and export a previewable MP4 with subtitles.</p></div><div className="voice-provider-badge ready"><span className="status-dot" />{catalog?.configured ? "Gemini TTS ready" : "Recorded audio fallback"}</div></div>{error && <div className="alert error"><X size={16} />{error}<button onClick={() => setError("")}><X size={15} /></button></div>}<div className="timeline-grid"><aside className="timeline-sidebar"><section className="card timeline-summary"><div className="voice-section-heading"><div><span className="eyebrow">TIMELINE SUMMARY</span><h2>Project inputs</h2></div></div><div className="timeline-stats"><div><strong>{segmentCount}</strong><span>SRT segments</span></div><div><strong>{videoFile ? "Ready" : "—"}</strong><span>MP4 source</span></div><div><strong>{audioFile ? "Upload" : catalog?.configured ? "AI" : "—"}</strong><span>Voice source</span></div></div><label className="field"><span>Timeline title</span><input value={title} maxLength={120} onChange={(event) => setTitle(event.target.value)} /></label><label className="field"><span>Attach to project (optional)</span><select value={projectId} onChange={(event) => setProjectId(event.target.value)}><option value="">Keep in timeline history</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.title}</option>)}</select></label></section><section className="card selected-voice-card"><span className="eyebrow">SELECTED VOICE</span><div className="selected-voice-icon"><Mic2 size={27} /></div><h2>{voice}</h2><p>{audioFile ? "Using uploaded narration" : "Gemini Khmer narration"}</p><label className="field"><span>Change voice</span><select value={voice} onChange={(event) => setVoice(event.target.value)}>{(catalog?.voices || [{ id: "Kore", label: "Kore", description: "Clear and balanced" }]).map((item) => <option key={item.id} value={item.id}>{item.label} · {item.description}</option>)}</select></label></section></aside><main className="timeline-main"><section className="card timeline-video-card"><div className="voice-section-heading"><div><span className="eyebrow">VIDEO PREVIEW</span><h2>{timeline ? "Generated timeline video" : "Choose your source video"}</h2></div><label className="file-picker compact-picker"><Film size={15} /><span>{videoFile?.name || "Choose MP4"}</span><input type="file" accept="video/mp4,.mp4" onChange={(event) => setVideoFile(event.target.files?.[0] || null)} /></label></div>{timeline ? <video className="timeline-preview" src={src(timeline.videoUrl)} controls preload="metadata" /> : <div className="timeline-empty-preview"><Film size={34} /><strong>MP4 video preview</strong><span>Your exported video will appear here.</span></div>}</section><section className="card subtitle-card"><div className="voice-section-heading"><div><span className="eyebrow">SUBTITLE · SRT</span><h2>Paste your Khmer subtitles</h2></div><span className="section-meta">{segmentCount} segments · {srt.length.toLocaleString()} chars</span></div><textarea className="srt-editor" value={srt} onChange={(event) => setSrt(event.target.value)} placeholder={'1\n00:00:00,000 --> 00:00:03,000\nសរសេរអត្ថបទខ្មែរនៅទីនេះ…'} /><label className="file-picker srt-upload"><FileAudio size={15} /><span>Or upload an SRT file</span><input type="file" accept=".srt,text/plain" onChange={async (event) => { const file = event.target.files?.[0]; if (file) setSrt(await file.text()); }} /></label></section><section className="card timeline-action-card"><div className="timeline-upload-row"><div><span className="eyebrow">VOICE SOURCE</span><h3>AI voice or your recording</h3><p>Gemini reads the SRT text, or upload a narration to keep the original performance.</p></div><label className="file-picker"><FileAudio size={15} /><span>{audioFile?.name || "Optional MP3/WAV"}</span><input type="file" accept="audio/mpeg,audio/wav,.mp3,.wav" onChange={(event) => setAudioFile(event.target.files?.[0] || null)} /></label></div><div className="timeline-action-footer"><span className="timeline-ready"><span className="status-dot" />Ready to export</span><button className="button primary" onClick={exportTimeline} disabled={busy || !videoFile || (!srt.trim() && !audioFile)}>{busy ? <Spinner /> : <><WandSparkles size={16} /> Generate timeline voice</>}</button>{timeline && <><a className="button secondary" href={`${timeline.downloadUrl}?token=${encodeURIComponent(token)}`}><Download size={15} /> Export MP4</a>{timeline.subtitleUrl && <a className="button ghost" href={`${timeline.subtitleUrl}?token=${encodeURIComponent(token)}`}><Download size={15} /> SRT</a>}</>}</div></section></main></div><section className="card timeline-history"><div className="voice-section-heading"><div><span className="eyebrow"><History size={13} /> TIMELINE HISTORY</span><h2>Previous exports</h2></div><span className="section-meta">{timelines.length} saved</span></div>{!timelines.length ? <div className="inline-empty"><Film size={18} /><span>No timeline exports yet.</span></div> : <div className="timeline-history-list">{timelines.map((item) => <button key={item.id} className={`voice-history-row ${timeline?.id === item.id ? "selected" : ""}`} onClick={() => setTimeline(item)}><div className="history-icon"><Film size={16} /></div><div><strong>{item.title}</strong><span>{item.voice} · {new Date(item.createdAt).toLocaleString()}</span></div><Play size={15} /></button>)}</div>}</section></section>;
}
